import assert from'node:assert/strict';import path from'node:path';import{writeFile,readFile}from'node:fs/promises';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{load}from'cheerio';import{calendarClock,calendarToday}from'../../scripts/calendar-clock.mjs';
const artifact=path.resolve('artifacts/platform/events-heldout'),origin='http://127.0.0.1:9440';let server,browser;const cases=[];
try{const clock=calendarClock(await(await fetch(origin+'/wp-json/')).json()),today=calendarToday(clock),month=today.slice(0,7),monthDay=month+'-01';server=await serveStatic(path.join(artifact,'project/output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){const pair=[];for(const [kind,url]of [['source',origin+'/events/month/'],['export',server.url+'/events/month/2028-03/?calendar-date=today']]){const page=await browser.newPage({viewport:{width,height:900},timezoneId:'Pacific/Pago_Pago'});assert.equal((await page.goto(url,{waitUntil:'networkidle'})).status(),200);if(kind==='export')await page.waitForFunction(day=>document.querySelector('.tribe-events-c-top-bar__datepicker-time')?.getAttribute('datetime')===day,monthDay);
 const states=await page.locator('.tribe-events-calendar-month__day').evaluateAll(es=>es.map(e=>({date:e.querySelector('time')?.getAttribute('datetime'),classes:[...e.classList].filter(c=>/tribe-events-calendar-month__day--/.test(c)).sort(),expanded:e.querySelector('.tribe-events-calendar-month__day-cell--mobile')?.getAttribute('aria-expanded')})));
 const current=states.find(e=>e.date===today);assert.ok(current.classes.includes('tribe-events-calendar-month__day--current'));assert.equal(current.expanded,'true');assert.equal(await page.locator('.tribe-events-calendar-month-mobile-events__mobile-day--show').count(),1);
 await page.locator('.tribe-events-calendar-month__day--current').screenshot({path:path.join(artifact,`today-cell-${kind}-${width}.png`)});pair.push({kind,states});
 if(kind==='export'&&width===1440){const next=page.locator('.tribe-events-c-top-bar__nav-link--next:visible,.tribe-events-c-nav__next:visible').first();await next.click();await page.waitForFunction(day=>document.querySelector('.tribe-events-c-top-bar__datepicker-time')?.getAttribute('datetime')!==day,monthDay);await page.locator('.tribe-events-c-top-bar__today-button').click();await page.waitForFunction(day=>document.querySelector('.tribe-events-c-top-bar__datepicker-time')?.getAttribute('datetime')===day,monthDay);}
 await page.close();}assert.deepEqual(pair[0].states,pair[1].states);cases.push({width,pair});}
 // The serialized destination must work before runtime rewrites it, including prefixed routes.
 const html=await readFile(path.join(artifact,'project/output/events/month/2028-03/index.html'),'utf8'),$=load(html),href=$('.tribe-events-c-top-bar__today-button').attr('href');assert.ok(href.endsWith('?calendar-date=today'));assert.equal((await fetch(server.url+href)).status,200);
 const result={scope:'Installed default month date-state classes and selected mobile panel, local Today deep link and desktop click; custom PHP filters remain unverified',clock,today,cases,serializedToday:href};await writeFile(path.join(artifact,'today-generated-check.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({cases:cases.length,today,serializedToday:href}));
}finally{await browser?.close();await server?.close();}
